-- Append-only auth target identity. Legacy rows retain every previous value.
ALTER TABLE kids_hosted_auth ADD intent TEXT;
--> statement-breakpoint
ALTER TABLE kids_hosted_auth ADD slot_id TEXT;
--> statement-breakpoint
ALTER TABLE kids_hosted_auth ADD slot_revision INTEGER;
--> statement-breakpoint
ALTER TABLE kids_hosted_auth ADD slot_epoch INTEGER CONSTRAINT kids_hosted_auth_target_shape CHECK((intent IS NULL AND slot_id IS NULL AND slot_revision IS NULL AND slot_epoch IS NULL) OR (intent IS NOT NULL AND intent IN ('add','reconnect') AND slot_id IS NOT NULL AND length(slot_id)=36 AND length(replace(slot_id,'-',''))=32 AND lower(slot_id) NOT GLOB '*[^a-f0-9-]*' AND substr(slot_id,9,1)='-' AND substr(slot_id,14,1)='-' AND substr(slot_id,19,1)='-' AND substr(slot_id,24,1)='-' AND slot_revision IS NOT NULL AND typeof(slot_revision)='integer' AND slot_revision>=1 AND slot_epoch IS NOT NULL AND typeof(slot_epoch)='integer' AND slot_epoch>=0));
--> statement-breakpoint
CREATE TRIGGER kids_hosted_auth_target_identity BEFORE UPDATE ON kids_hosted_auth WHEN NEW.intent IS NOT OLD.intent OR NEW.slot_id IS NOT OLD.slot_id OR NEW.slot_revision IS NOT OLD.slot_revision OR NEW.slot_epoch IS NOT OLD.slot_epoch BEGIN SELECT RAISE(ABORT,'KIDS_AUTH_TARGET_IMMUTABLE'); END;
--> statement-breakpoint
CREATE TRIGGER kids_hosted_auth_target_insert BEFORE INSERT ON kids_hosted_auth BEGIN
 SELECT CASE WHEN NEW.intent IS NOT NULL AND (NEW.verified_binding_id IS NOT NULL OR NEW.verified_identity_hash IS NOT NULL OR NEW.completed_at IS NOT NULL OR NEW.sync_status IS NOT NULL OR NEW.state_hash IS NOT NULL OR NEW.auth_link IS NOT NULL OR (NEW.recovery_of IS NULL AND (NEW.candidate_account_id IS NOT NULL OR NEW.recovery_result IS NOT NULL OR NEW.status<>CASE WHEN NEW.scope_id IS NULL THEN 'scope_creating' ELSE 'scope_ready' END)) OR (NEW.recovery_of IS NOT NULL AND (NEW.status<>'verifying' OR NEW.recovery_result IS NOT 'checking'))) THEN RAISE(ABORT,'KIDS_AUTH_INITIAL_STATE') END;
 SELECT CASE WHEN NEW.intent IS NULL AND EXISTS(SELECT 1 FROM kids_source_connections s WHERE s.owner_user_id=NEW.owner_user_id AND s.workspace_id=NEW.workspace_id) THEN RAISE(ABORT,'KIDS_AUTH_TARGET_REQUIRED') END;
 SELECT CASE WHEN NEW.intent IS NOT NULL AND (EXISTS(SELECT 1 FROM kids_operation_receipts WHERE owner_user_id=NEW.owner_user_id AND operation_id=NEW.operation_id) OR EXISTS(SELECT 1 FROM kids_hosted_batches WHERE owner_user_id=NEW.owner_user_id AND operation_id=NEW.operation_id) OR EXISTS(SELECT 1 FROM kids_hosted_history_pages WHERE owner_user_id=NEW.owner_user_id AND operation_id=NEW.operation_id) OR EXISTS(SELECT 1 FROM kids_hosted_removals WHERE owner_user_id=NEW.owner_user_id AND operation_id=NEW.operation_id)) THEN RAISE(ABORT,'KIDS_AUTH_OPERATION_CONFLICT') END;
 SELECT CASE WHEN NEW.intent IS NOT NULL AND NEW.recovery_of IS NOT NULL AND (NOT EXISTS(SELECT 1 FROM kids_source_connections s WHERE s.id=NEW.slot_id AND s.owner_user_id=NEW.owner_user_id AND s.workspace_id=NEW.workspace_id AND s.revision=NEW.slot_revision AND s.source_epoch=NEW.slot_epoch AND s.discovery_consent=1 AND s.paused=0 AND ((NEW.intent='add' AND s.status='reserved' AND s.binding_id IS NULL AND s.processing_consent=0) OR (NEW.intent='reconnect' AND s.status='connected' AND s.binding_id=NEW.binding_id AND s.id=NEW.binding_id))) OR NOT EXISTS(SELECT 1 FROM kids_hosted_auth old WHERE old.owner_user_id=NEW.owner_user_id AND old.workspace_id=NEW.workspace_id AND old.operation_id=NEW.recovery_of AND old.status='expired' AND old.expires_at<=CAST((julianday('now')-2440587.5)*86400000 AS INTEGER) AND old.intent=NEW.intent AND old.slot_id=NEW.slot_id AND old.slot_revision=NEW.slot_revision AND old.slot_epoch=NEW.slot_epoch AND old.scope_id=NEW.scope_id AND old.scope_reference=NEW.scope_reference AND old.binding_id IS NEW.binding_id AND old.binding_revision IS NEW.binding_revision AND old.expected_account_id IS NEW.expected_account_id AND old.expected_identity_hash IS NEW.expected_identity_hash AND old.candidate_account_id IS NEW.candidate_account_id)) THEN RAISE(ABORT,'KIDS_AUTH_RECOVERY_TARGET') END;
 SELECT CASE WHEN NEW.intent='reconnect' AND (NOT EXISTS(SELECT 1 FROM kids_source_connections s WHERE s.id=NEW.slot_id AND s.owner_user_id=NEW.owner_user_id AND s.workspace_id=NEW.workspace_id AND s.revision=NEW.slot_revision AND s.source_epoch=NEW.slot_epoch AND s.discovery_consent=1 AND s.paused=0 AND ((NEW.intent='add' AND s.status='reserved' AND s.binding_id IS NULL AND s.processing_consent=0) OR (NEW.intent='reconnect' AND s.status='connected' AND s.binding_id=NEW.binding_id AND s.id=NEW.binding_id))) OR NEW.binding_id<>NEW.slot_id OR NOT EXISTS(SELECT 1 FROM kids_hosted_bindings b JOIN kids_hosted_auth old ON old.verified_binding_id=b.id AND old.scope_id=b.scope_id AND old.status='connected' AND old.scope_reference=NEW.scope_reference WHERE b.id=NEW.binding_id AND b.owner_user_id=NEW.owner_user_id AND b.workspace_id=NEW.workspace_id AND old.owner_user_id=b.owner_user_id AND old.workspace_id=b.workspace_id AND b.revision=NEW.binding_revision AND b.account_id=NEW.expected_account_id AND b.provider_identity_hash=NEW.expected_identity_hash AND b.scope_id=NEW.scope_id AND b.application_id=NEW.application_id AND b.production=NEW.production AND b.endpoint_id=NEW.endpoint_id AND b.removed_at IS NULL AND NEW.scope_reference IN ('familyops:'||NEW.workspace_id,'familyops:'||NEW.workspace_id||':slot:'||NEW.slot_id))) THEN RAISE(ABORT,'KIDS_AUTH_RECONNECT_TARGET') END;
 SELECT CASE WHEN NEW.intent='add' AND (NEW.binding_id IS NOT NULL OR NEW.binding_revision IS NOT NULL OR NEW.expected_account_id IS NOT NULL OR NEW.expected_identity_hash IS NOT NULL OR NEW.scope_reference<>'familyops:'||NEW.workspace_id||':slot:'||NEW.slot_id) THEN RAISE(ABORT,'KIDS_AUTH_ADD_TARGET') END;
 SELECT CASE WHEN NEW.intent='add' AND NEW.recovery_of IS NULL AND EXISTS(SELECT 1 FROM kids_source_connections WHERE id=NEW.slot_id) AND (NOT EXISTS(SELECT 1 FROM kids_source_connections s WHERE s.id=NEW.slot_id AND s.owner_user_id=NEW.owner_user_id AND s.workspace_id=NEW.workspace_id AND s.revision=NEW.slot_revision AND s.source_epoch=NEW.slot_epoch AND s.discovery_consent=1 AND s.paused=0 AND ((NEW.intent='add' AND s.status='reserved' AND s.binding_id IS NULL AND s.processing_consent=0) OR (NEW.intent='reconnect' AND s.status='connected' AND s.binding_id=NEW.binding_id AND s.id=NEW.binding_id))) OR NOT EXISTS(SELECT 1 FROM kids_hosted_auth old WHERE old.owner_user_id=NEW.owner_user_id AND old.workspace_id=NEW.workspace_id AND old.slot_id=NEW.slot_id AND old.operation_id=(SELECT operation_id FROM kids_hosted_auth WHERE owner_user_id=NEW.owner_user_id AND workspace_id=NEW.workspace_id AND slot_id=NEW.slot_id ORDER BY created_at DESC,rowid DESC LIMIT 1) AND old.intent='add' AND old.status='failed' AND old.recovery_result='empty' AND old.candidate_account_id IS NULL AND old.recovery_of IS NOT NULL AND old.scope_id=NEW.scope_id AND old.scope_reference=NEW.scope_reference AND old.slot_revision=NEW.slot_revision AND old.slot_epoch=NEW.slot_epoch)) THEN RAISE(ABORT,'KIDS_AUTH_RESERVED_REUSE') END;
 SELECT CASE WHEN NEW.intent='add' AND NOT EXISTS(SELECT 1 FROM kids_source_connections WHERE id=NEW.slot_id) AND (NEW.recovery_of IS NOT NULL OR NEW.scope_id IS NOT NULL OR NEW.slot_revision<>1 OR NEW.slot_epoch<>0 OR EXISTS(SELECT 1 FROM kids_source_connections WHERE owner_user_id=NEW.owner_user_id AND workspace_id=NEW.workspace_id AND status='reserved') OR (SELECT COUNT(*) FROM kids_source_connections WHERE owner_user_id=NEW.owner_user_id AND workspace_id=NEW.workspace_id AND status<>'removed')>=2 OR EXISTS(SELECT 1 FROM kids_hosted_bindings b WHERE b.owner_user_id=NEW.owner_user_id AND b.workspace_id=NEW.workspace_id AND b.removed_at IS NULL AND NOT EXISTS(SELECT 1 FROM kids_source_connections s WHERE s.owner_user_id=b.owner_user_id AND s.workspace_id=b.workspace_id AND s.binding_id=b.id AND s.status='connected'))) THEN RAISE(ABORT,'KIDS_AUTH_SLOT_LIMIT_OR_PREPARATION') END;
END;
