CREATE TRIGGER kids_hosted_auth_reserve_slot AFTER INSERT ON kids_hosted_auth WHEN NEW.intent IS NOT NULL BEGIN
 INSERT INTO kids_source_connections(id,owner_user_id,workspace_id,slot_number,binding_id,label,status,revision,source_epoch,discovery_consent,processing_consent,confirmed_at,paused,created_at,updated_at)
 SELECT NEW.slot_id,NEW.owner_user_id,NEW.workspace_id,CASE WHEN NOT EXISTS(SELECT 1 FROM kids_source_connections WHERE owner_user_id=NEW.owner_user_id AND workspace_id=NEW.workspace_id AND slot_number=1 AND status<>'removed') THEN 1 ELSE 2 END,NULL,
 CASE WHEN NOT EXISTS(SELECT 1 FROM kids_source_connections WHERE owner_user_id=NEW.owner_user_id AND workspace_id=NEW.workspace_id AND slot_number=1 AND status<>'removed') THEN 'WhatsApp 1' ELSE 'WhatsApp 2' END,'reserved',1,0,1,0,NULL,0,NEW.created_at,NEW.created_at
 WHERE NEW.intent='add' AND NEW.recovery_of IS NULL AND NOT EXISTS(SELECT 1 FROM kids_source_connections WHERE id=NEW.slot_id);
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM kids_source_connections s WHERE s.id=NEW.slot_id AND s.owner_user_id=NEW.owner_user_id AND s.workspace_id=NEW.workspace_id AND s.revision=NEW.slot_revision AND s.source_epoch=NEW.slot_epoch AND s.discovery_consent=1 AND s.paused=0 AND ((NEW.intent='add' AND s.status='reserved' AND s.binding_id IS NULL AND s.processing_consent=0) OR (NEW.intent='reconnect' AND s.status='connected' AND s.binding_id=NEW.binding_id AND s.id=NEW.binding_id))) THEN RAISE(ABORT,'KIDS_AUTH_SLOT_UNCONFIRMED') END;
END;
--> statement-breakpoint
CREATE TRIGGER kids_hosted_auth_complete_v2 AFTER UPDATE OF status ON kids_hosted_auth WHEN NEW.status='connected' BEGIN
SELECT CASE WHEN (NEW.intent IS NULL AND EXISTS(SELECT 1 FROM kids_source_connections s WHERE s.owner_user_id=NEW.owner_user_id AND s.workspace_id=NEW.workspace_id)) OR (NEW.intent IS NOT NULL AND (NEW.verified_binding_id IS NOT NEW.slot_id OR NOT EXISTS(SELECT 1 FROM kids_source_connections s WHERE s.id=NEW.slot_id AND s.owner_user_id=NEW.owner_user_id AND s.workspace_id=NEW.workspace_id AND s.revision=NEW.slot_revision AND s.source_epoch=NEW.slot_epoch AND s.discovery_consent=1 AND s.paused=0 AND ((NEW.intent='add' AND s.status='reserved' AND s.binding_id IS NULL AND s.processing_consent=0) OR (NEW.intent='reconnect' AND s.status='connected' AND s.binding_id=NEW.binding_id AND s.id=NEW.binding_id))))) THEN RAISE(ABORT,'KIDS_AUTH_SLOT_UNCONFIRMED') END;
 SELECT CASE WHEN OLD.status<>'verifying' OR NEW.verified_binding_id IS NULL OR NEW.verified_identity_hash IS NULL
  OR length(NEW.verified_identity_hash)<>64 OR NEW.verified_identity_hash GLOB '*[^a-f0-9]*'
  OR NEW.candidate_account_id IS NULL OR NEW.scope_id IS NULL OR NEW.completed_at IS NULL
  OR (NEW.expected_account_id IS NOT NULL AND NEW.candidate_account_id<>NEW.expected_account_id)
  OR (NEW.expected_identity_hash IS NOT NULL AND NEW.verified_identity_hash<>NEW.expected_identity_hash)
  THEN RAISE(ABORT,'KIDS_HOSTED_BINDING_UNCONFIRMED') END;
 INSERT INTO kids_hosted_bindings(id,owner_user_id,workspace_id,application_id,production,endpoint_id,scope_id,account_id,revision,active,consent_version,created_at,reconciliation_reason,provider_identity_hash)
 SELECT NEW.verified_binding_id,NEW.owner_user_id,NEW.workspace_id,NEW.application_id,NEW.production,NEW.endpoint_id,NEW.scope_id,NEW.candidate_account_id,1,1,NEW.consent_version,NEW.completed_at,'history_reconciliation_required',NEW.verified_identity_hash
 WHERE NEW.binding_id IS NULL;
 UPDATE kids_hosted_bindings SET active=1,revision=revision+1,reconciliation_reason=COALESCE(reconciliation_reason,'history_reconciliation_required')
 WHERE NEW.binding_id IS NOT NULL AND id=NEW.binding_id AND id=NEW.verified_binding_id
  AND owner_user_id=NEW.owner_user_id AND workspace_id=NEW.workspace_id AND application_id=NEW.application_id
  AND production=NEW.production AND endpoint_id=NEW.endpoint_id AND scope_id=NEW.scope_id
  AND account_id=NEW.candidate_account_id AND provider_identity_hash=NEW.verified_identity_hash AND revision=NEW.binding_revision;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM kids_hosted_bindings WHERE id=NEW.verified_binding_id
  AND owner_user_id=NEW.owner_user_id AND workspace_id=NEW.workspace_id AND application_id=NEW.application_id
  AND production=NEW.production AND endpoint_id=NEW.endpoint_id AND scope_id=NEW.scope_id
  AND account_id=NEW.candidate_account_id AND provider_identity_hash=NEW.verified_identity_hash AND active=1
  AND revision=CASE WHEN NEW.binding_id IS NULL THEN 1 ELSE NEW.binding_revision+1 END)
  THEN RAISE(ABORT,'KIDS_HOSTED_BINDING_UNCONFIRMED') END;
UPDATE kids_source_connections SET binding_id=NEW.verified_binding_id,status='connected',revision=revision+1,source_epoch=source_epoch+1,processing_consent=0,confirmed_at=NULL,updated_at=NEW.completed_at WHERE NEW.intent IS NOT NULL AND id=NEW.slot_id AND owner_user_id=NEW.owner_user_id AND workspace_id=NEW.workspace_id AND revision=NEW.slot_revision AND source_epoch=NEW.slot_epoch;
 SELECT CASE WHEN NEW.intent IS NOT NULL AND NOT EXISTS(SELECT 1 FROM kids_source_connections s WHERE s.id=NEW.slot_id AND s.owner_user_id=NEW.owner_user_id AND s.workspace_id=NEW.workspace_id AND s.binding_id=NEW.verified_binding_id AND s.status='connected' AND s.revision=NEW.slot_revision+1 AND s.source_epoch=NEW.slot_epoch+1 AND s.processing_consent=0 AND s.confirmed_at IS NULL AND s.discovery_consent=1 AND s.paused=0) THEN RAISE(ABORT,'KIDS_AUTH_SLOT_UNCONFIRMED') END;
END;
--> statement-breakpoint
DROP TRIGGER kids_hosted_auth_complete;
